CREATE INDEX "IX_Floors_AllowedVehicleTypeId" ON "Floors" ("AllowedVehicleTypeId");

CREATE INDEX "IX_ParkingSlots_FloorId_Status" ON "ParkingSlots" ("FloorId", "Status");

SELECT setval(
    pg_get_serial_sequence('"VehicleTypes"', 'Id'),
    GREATEST(
        (SELECT MAX("Id") FROM "VehicleTypes") + 1,
        nextval(pg_get_serial_sequence('"VehicleTypes"', 'Id'))),
    false);

